document.addEventListener("DOMContentLoaded", function () {

    /* ONLY Portfolio Category Archive Pages */
    if (document.body.classList.contains("tax-portfolio_cat")) {

        /* =========================
           CATEGORY HEADER BACKGROUND
        ========================== */

        const pageHeader = document.querySelector(".page-header");

        if (pageHeader) {
            pageHeader.style.backgroundImage = 'url("https://seagreen-leopard-259647.hostingersite.com/assets/images/2026/03/Aboust-Us-HEro-Bg.png")';
            pageHeader.style.backgroundSize = "contain";
            pageHeader.style.backgroundPosition = "center center";
            pageHeader.style.backgroundRepeat = "no-repeat";
            pageHeader.style.backgroundColor = "transparent";
        }

        /* =========================
           REMOVE "Categories:"
        ========================== */

        const pageTitle = document.querySelector(".page-title");

        if (pageTitle) {

            pageTitle.innerHTML = pageTitle.innerHTML
                .replace("Categories:", "")
                .replace("Category:", "")
                .trim();
        }

        /* =========================
           REMOVE TOP PADDING ONLY
           FOR CATEGORY PAGES
        ========================== */

        const entryContent = document.querySelector(".entry-content");

        if (entryContent) {
            entryContent.style.paddingTop = "0px";
        }

    }

});